use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

const MAX_TOOL_ROUNDS: u32 = 4;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let system = "You are a customer support assistant. Answer the question \
                       using the provided knowledge; use the lookup tool if you \
                       need more information."
            .to_string();

        let mut prompt = format!(
            "Question: {}\n\nKnowledge:\n{}",
            ctx.question,
            ctx.knowledge.join("\n")
        );

        let mut rounds = 0u32;
        loop {
            let reply = tool_llm::generate(&system, &prompt);
            match reply {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool != "lookup" {
                        return ResponseResult::Error(LlmError {
                            message: format!("unsupported tool requested: {}", req.tool),
                        });
                    }

                    rounds += 1;
                    if rounds > MAX_TOOL_ROUNDS {
                        return ResponseResult::Error(LlmError {
                            message: "exceeded maximum tool-call rounds".to_string(),
                        });
                    }

                    let results = kb_read::lookup(&req.query);
                    prompt = format!(
                        "{}\n\nTool lookup(\"{}\") returned:\n{}",
                        prompt,
                        req.query,
                        results.join("\n")
                    );
                }
            }
        }
    }
}

export!(Node);
```

